const lead = $('Extract Research Text').first().json;
const cfg = $('Config').first().json;
const raw = String($json.text || '');

let q;
let aiError = false;
try {
  const m = raw.match(/\{[\s\S]*\}/);
  q = JSON.parse(m ? m[0] : raw);
} catch (e) {
  aiError = true;
  q = { score: 0, fit_reason: 'AI call failed or returned unparseable output', business_summary: '', pain_points: [], personalization_hook: '', recommended_angle: '' };
}

const score = Number(q.score) || 0;

return {
  json: {
    ...lead,
    ...q,
    score,
    pain_points: Array.isArray(q.pain_points) ? q.pain_points : [],
    qualified: !aiError && score >= Number(cfg.min_score),
    ai_error: aiError,
    has_email: !!lead.email
  }
};

parameters.text:
=Write a short first-touch email to this business.

SENDER: {{ $('Config').first().json.sender_name }} from {{ $('Config').first().json.sender_company }}
WHAT WE OFFER: {{ $('Config').first().json.my_offer }}

RECIPIENT
Business: {{ $json.name }} ({{ $json.category }})
What they do: {{ $json.business_summary }}
Likely pain points: {{ $json.pain_points.join('; ') }}
Personalization hook: {{ $json.personalization_hook }}
Recommended angle: {{ $json.recommended_angle }}

RULES
- Language: {{ $('Config').first().json.email_language }}
- Body max 110 words, plain text, no markdown, no emojis.
- Open with the personalization hook. If it is empty, address the business by name.
- One concrete benefit. No invented numbers.
- End with one low-pressure question.
- Do NOT include a signature or opt-out line; they are added automatically.

Return ONLY valid JSON with exactly these keys, no markdown fences:
{"subject": "max 7 words, no clickbait", "body": "email body, use \n for line breaks"}

parameters.jsCode:
const lead = $('Parse Qualification').item.json;
const cfg = $('Config').first().json;
const raw = String($json.text || '');

let o = {};
try {
  const m = raw.match(/\{[\s\S]*\}/);
  o = JSON.parse(m ? m[0] : raw);
} catch (e) {}

const parseFailed = !o.body;
const subject = String(o.subject || `Quick idea for ${lead.name}`).trim();
const body = parseFailed
  ? `Hi ${lead.name} team,\n\n${lead.recommended_angle || cfg.my_offer}\n\nWould it be worth a quick chat?`
  : String(o.body).trim();

const footer = `\n\n${cfg.sender_name}\n${cfg.sender_company}\n\n${cfg.opt_out_line}`;

return { json: { ...lead, subject, email_body: body + footer, parse_failed: parseFailed } };

